        #region Load Rules
        public void LoadObjectTableRulesANDFieldsValidations()
        {
            ObjectContext = WebFreightContext.GetContext(0);
            ObjectTableRuleRepository = new ObjectTableRuleRepository(ObjectContext);
            ObjectTableRuleFieldRepository = new ObjectTableRuleFieldRepository(ObjectContext);
            ObjectFieldValidationRepository = new ObjectFieldValidationRepository(ObjectContext);
            RuleConditionFieldRepository = new RuleConditionFieldRepository(ObjectContext);
            Dictionary<string, ObjectTableRule> TenantObjectTableRule = ObjectTableRuleRepository.GetObjectTableRules(0).ToDictionary(d => d.RuleCode, a => a);
            Dictionary<string, ObjectTableRuleField> TenantObjectTableRuleFields = ObjectTableRuleFieldRepository.GetObjectTableRuleFields(0).ToDictionary(d => d.ObjectTableRuleId + d.ObjectFieldId, a => a);
            Dictionary<string, RuleConditionField> TenantRuleConditionFields = RuleConditionFieldRepository.GetRuleConditionFieldsByTenant(0).ToDictionary(d => d.ObjectTableRuleId + d.ObjectFieldCode, a => a);
            List<ObjectFieldValidation> TenantObjectFieldValidations = ObjectFieldValidationRepository.GetObjectFieldValidations(0).ToList();

            CreateClientRules(TenantObjectTableRule, TenantObjectTableRuleFields, TenantObjectFieldValidations);
            CreateCustomBankRules(TenantObjectTableRule, TenantObjectTableRuleFields, TenantObjectFieldValidations);

        }

        #region ClientRules
        private void CreateClientRules(Dictionary<string, ObjectTableRule> TenantObjectTableRule, Dictionary<string, ObjectTableRuleField> TenantObjectTableRuleFields, List<ObjectFieldValidation> TenantObjectFieldValidations)
        {

            ObjectTable ClientTable = ObjectContext.ObjectTables.Where(f => f.Name == "Customs.Client" && f.Tenant == 0).FirstOrDefault();
            ObjectField ClientCode = ObjectContext.ObjectFields.Where(d => d.FieldName == "Code" && d.ObjectTableId == ClientTable.Id).FirstOrDefault();

            ObjectTableRule ClientDuplicationRule = AddObjectTableRules.AddObjectTableRule(new ObjectTableRuleDetails()
            {
                RuleCode = "CLND",
                Name = "Code Duplication",
                ObjectTableId = ClientTable.Id,
                Tenant = 0,
                RuleTypeCode = "DUPL",
                //TriggerFieldId = ClientCode.Id,
                SystemLevel = true,
                OutputMessage = "This Client already exists",
                ActiveForNew = true,
                ActiveForUpdate = false,
                TriggerTypeCode = "ALLW",
                RuleNotificationTypeCode = "ERR",
            }, ObjectTableRuleRepository, TenantObjectTableRule);

            ObjectTableRuleField ClientCodeField = AddObjectTableRules.AddObjectTableRuleField(new ObjectTableRuleFieldDetails() { ObjectFieldId = ClientCode.Id, ObjectFieldCode = ClientCode.FieldCode, ObjectTableRuleId = ClientDuplicationRule.Id, SystemLevel = true, Tenant = 0 }, ObjectTableRuleFieldRepository, TenantObjectTableRuleFields);


            ObjectContext.SaveChanges();

        }

        #endregion

        #region CustomBankRules
        private void CreateCustomBankRules(Dictionary<string, ObjectTableRule> TenantObjectTableRule, Dictionary<string, ObjectTableRuleField> TenantObjectTableRuleFields, List<ObjectFieldValidation> TenantObjectFieldValidations)
        {

            ObjectTable CustomBankTable = ObjectContext.ObjectTables.Where(f => f.Name == "Customs.CustomBank" && f.Tenant == 0).FirstOrDefault();
            ObjectField InternalCode = ObjectContext.ObjectFields.Where(d => d.FieldName == "InternalCode" && d.ObjectTableId == CustomBankTable.Id).FirstOrDefault();

            ObjectTableRule CustomBankDuplicationRule = AddObjectTableRules.AddObjectTableRule(new ObjectTableRuleDetails()
            {
                RuleCode = "CBID",
                Name = "Code Duplication",
                ObjectTableId = CustomBankTable.Id,
                Tenant = 0,
                RuleTypeCode = "DUPL",

                SystemLevel = true,
                OutputMessage = "This Internal Code already exists",
                ActiveForNew = true,
                ActiveForUpdate = false,
                TriggerTypeCode = "ALLW",
                RuleNotificationTypeCode = "ERR",
            }, ObjectTableRuleRepository, TenantObjectTableRule);

            ObjectTableRuleField CustomBankCodeField = AddObjectTableRules.AddObjectTableRuleField(new ObjectTableRuleFieldDetails() { ObjectFieldId = InternalCode.Id, ObjectFieldCode = InternalCode.FieldCode, ObjectTableRuleId = CustomBankDuplicationRule.Id, SystemLevel = true, Tenant = 0 }, ObjectTableRuleFieldRepository, TenantObjectTableRuleFields);


            ObjectContext.SaveChanges();

        }

