        #region Closed Tables

        public void LoadBaseTablesForDataBases()
        {
            string enviroment = ConfigurationManager.AppSettings.Get("ENVIROMENT");
            if (enviroment == "azure app service")
                LoadBaseTablesForConnection(ConfigurationManager.ConnectionStrings["SystemMainStr"].ConnectionString);

            else
            {
                GlobalDBRepository globalDbRep = new GlobalDBRepository();
                List<GlobalDB> dbList = globalDbRep.GetGlobalDBs().ToList();

                foreach (GlobalDB db in dbList)
                {
                    LoadBaseTablesForConnection(db.DBConnection);
                }
            }
        }

        public void UpgradeClosedTablesForTenantZero()
        {
            isUpdate = true;

            string enviroment = ConfigurationManager.AppSettings.Get("ENVIROMENT");
            if (enviroment == "azure app service")
                LoadBaseTablesForConnection(ConfigurationManager.ConnectionStrings["SystemMainStr"].ConnectionString);

            else
            {
                List<GlobalDB> dbList = null;
                using (TransactionScope scop = TransactionFactory.GetNewTransaction(new TimeSpan(0, 5, 0)))//new TransactionScope(TransactionScopeOption.RequiresNew, new TimeSpan(0, 5, 0)))
                {
                    GlobalDBRepository globalDbRep = new GlobalDBRepository();
                    dbList = globalDbRep.GetGlobalDBs().ToList();
                    scop.Complete();
                }

                foreach (GlobalDB db in dbList)
                {
                    LoadBaseTablesForConnection(db.DBConnection);
                }
            }
        }

        private void LoadBaseTablesForConnection(string connectionStr)
        {
            CustomContext customContext = new CustomContext(DatabaseInitializer.GetConnection(connectionStr));


            //-------------Password Policy---------------

            PhysicalCheckOperationRepository physicalCheckOperationRepository = new PhysicalCheckOperationRepository(customContext);
            AddClosedTables.AddPhysicalCheckOperation(new PhysicalCheckOperationDetails() { Code = "1", EnglishName = "Invite", LocalName = "זימון" }, physicalCheckOperationRepository);
            AddClosedTables.AddPhysicalCheckOperation(new PhysicalCheckOperationDetails() { Code = "2", EnglishName = "Update", LocalName = "עדכון" }, physicalCheckOperationRepository);
            AddClosedTables.AddPhysicalCheckOperation(new PhysicalCheckOperationDetails() { Code = "3", EnglishName = "Cancel", LocalName = "ביטול" }, physicalCheckOperationRepository);
            AddClosedTables.AddPhysicalCheckOperation(new PhysicalCheckOperationDetails() { Code = "4", EnglishName = "Cancel Invitation", LocalName = "ביטול יזום" }, physicalCheckOperationRepository);
            AddClosedTables.AddPhysicalCheckOperation(new PhysicalCheckOperationDetails() { Code = "5", EnglishName = "End - moved to another site", LocalName = "סיום -העברה לאתר אחר" }, physicalCheckOperationRepository);
            AddClosedTables.AddPhysicalCheckOperation(new PhysicalCheckOperationDetails() { Code = "6", EnglishName = "End - Moved to Customer", LocalName = "סיום -העברה לאתר אחר" }, physicalCheckOperationRepository);

            physicalCheckOperationRepository.SubmitChanges();


            PhysicalCheckStatusMessageRepository physicalCheckStatusMessageRepository = new PhysicalCheckStatusMessageRepository(customContext);
            AddClosedTables.AddPhysicalCheckStatusMessage(new PhysicalCheckStatusMessageDetails() { Code = "1", EnglishName = "First Transmition", LocalName = "שליחה ראשונית" }, physicalCheckStatusMessageRepository);
            AddClosedTables.AddPhysicalCheckStatusMessage(new PhysicalCheckStatusMessageDetails() { Code = "2", EnglishName = "Last Transmition", LocalName = "שליחה סופית" }, physicalCheckStatusMessageRepository);

            physicalCheckStatusMessageRepository.SubmitChanges();


            ClosedTableStatusRepository closedTableStatusRepository = new ClosedTableStatusRepository(customContext);
            AddClosedTables.AddClosedTableStatus(new ClosedTableStatusDetails() { Code = "1", EnglishName = "New", LocalName = "חדש", }, closedTableStatusRepository);
            AddClosedTables.AddClosedTableStatus(new ClosedTableStatusDetails() { Code = "2", EnglishName = "Updating", LocalName = "מעדכן", }, closedTableStatusRepository);
            AddClosedTables.AddClosedTableStatus(new ClosedTableStatusDetails() { Code = "3", EnglishName = "Up ToDate", LocalName = "מעודכן", }, closedTableStatusRepository);

            closedTableStatusRepository.SubmitChanges();

            CustomsEnvoirmentTypeRepository customsEnvoirmentTypeRepository = new CustomsEnvoirmentTypeRepository(customContext);
            AddClosedTables.AddCustomsEnvoirmentType(new CustomsEnvoirmentTypeDetails() { Code = ((int)CustomsDeploymentStage.PrePilot).ToString() /* "1" */, EnglishName = "PrePilot", LocalName = "פיילוט רשות", }, customsEnvoirmentTypeRepository);
            AddClosedTables.AddCustomsEnvoirmentType(new CustomsEnvoirmentTypeDetails() { Code = ((int)CustomsDeploymentStage.Pilot).ToString() /* "2" */, EnglishName = "Pilot", LocalName = "פיילוט חובה", }, customsEnvoirmentTypeRepository);
            AddClosedTables.AddCustomsEnvoirmentType(new CustomsEnvoirmentTypeDetails() { Code = ((int)CustomsDeploymentStage.Production).ToString()  /* "3" */, EnglishName = "Production", LocalName = "ייצור", }, customsEnvoirmentTypeRepository);

            AddClosedTables.AddCustomsEnvoirmentType(new CustomsEnvoirmentTypeDetails() { Code = ((int)CustomsDeploymentStage.Test).ToString()  /* "3" */, EnglishName = "Test", LocalName = "בדיקות", }, customsEnvoirmentTypeRepository);

            AddClosedTables.AddCustomsEnvoirmentType(new CustomsEnvoirmentTypeDetails() { Code = ((int)CustomsDeploymentStage.PREPROD).ToString()  /* "5" */, EnglishName = "PRE Production", LocalName = "קדם יצור", }, customsEnvoirmentTypeRepository);

            customsEnvoirmentTypeRepository.SubmitChanges();
            AddNewDeclarationErrorMappingSample();

        }
        public void AddNewDeclarationErrorMappingSample()
        {
            ICustomContext context = CustomContext.GetContext(0);
            DeclarationErrorMappingUpdateService declarationErrorMappingUpdateService = new DeclarationErrorMappingUpdateService(context, new Dictionary<string, IContext>(), 0);
            DeclarationErrorMappingPM newdeclarationError = new DeclarationErrorMappingPM()
            {
                Id = IdCounter.GetNumber("Customs.DeclarationErrorMapping", 0),
                ChangeSetOp = ChangeSetOperation.Insert,
                DocumentSectionCode = "ABC",
                Entity = "SampleEntity",
                Field = "SampleField",
                Skip = false,
                TagID = "123",
            };
            declarationErrorMappingUpdateService.Update(newdeclarationError, true);
        }
