        #region counters
        public void CreateTableCounters(int tenant)
        {
            ObjectContext = WebFreightContext.GetContext(0);
            ObjectTable declarationObject = ObjectContext.ObjectTables.Where(d => d.Name == "Customs.Declaration" && d.Tenant == 0).FirstOrDefault();
            CounterDefinitionRepository = new CounterDefinitionRepository(ObjectContext);
            CounterRepository = new CounterRepository(ObjectContext);
            //List<Counter> zeroCounters = CounterRepository.GetCounters(0).ToList();
            #region declaration Counters

            Counter counter = CounterRepository.GetCounterByCode("DECL", tenant);
            if (counter == null)
            {
                Counter declarationCounter = new Counter()
                {
                    Id = IdCounter.GetNumber("Counter", tenant).ToString(),
                    ObjectTableId = declarationObject.Id,
                    Code = "DECL",
                    Tenant = tenant,
                    Name = "Custom File No",
                };

                CounterDefinition declaration_CounterDef = new CounterDefinition()
                {
                    Id = IdCounter.GetNumber("CounterDefinition", tenant).ToString(),
                    CounterId = declarationCounter.Id,
                    Tenant = tenant,
                    StartNumber = 1000,
                    Parameter1 = "DC",
                };

                CounterRepository.Add(declarationCounter);
                CounterDefinitionRepository.Add(declaration_CounterDef);

            }
            #endregion

            #region QuoteOP Counters

            var objectTablesQuoteOP = ObjectContext.ObjectTables.Where(o => o.Name == "QuoteOP").FirstOrDefault();
            Counter counterQUOTOP = CounterRepository.GetCounterByCode("QTOP", tenant);
            if (objectTablesQuoteOP != null && counterQUOTOP == null)
            {
                Counter quoteCounter = new Counter()
                {
                    Id = IdCounter.GetNumber("Counter", 0).ToString(),
                    ObjectTableId = objectTablesQuoteOP.Id,//QuoteObject.Id,
                    Code = "QTOP",
                    Tenant = 0,
                    Name = "Quote(OP)",

                };

                CounterRepository.Add(quoteCounter);

                CounterDefinition Quote_Export_Air_Counter = new CounterDefinition()
                {
                    Id = IdCounter.GetNumber("CounterDefinition", 0).ToString(),
                    CounterId = quoteCounter.Id,
                    Tenant = 0,
                    StartNumber = 1000,
                    Parameter1 = "E",
                    Parameter2 = "A",
                };
                CounterDefinition Quote_Export_Ocean_Counter = new CounterDefinition()
                {
                    Id = IdCounter.GetNumber("CounterDefinition", 0).ToString(),
                    CounterId = quoteCounter.Id,
                    Tenant = 0,
                    StartNumber = 1000,
                    Parameter1 = "E",
                    Parameter2 = "O",
                };

                CounterDefinition Quote_Export_Inland_Counter = new CounterDefinition()
                {
                    Id = IdCounter.GetNumber("CounterDefinition", 0).ToString(),
                    CounterId = quoteCounter.Id,
                    Tenant = 0,
                    StartNumber = 1000,
                    Parameter1 = "E",
                    Parameter2 = "I",
                };

                CounterDefinition Quote_Import_Air_Counter = new CounterDefinition()
                {
                    Id = IdCounter.GetNumber("CounterDefinition", 0).ToString(),
                    CounterId = quoteCounter.Id,
                    Tenant = 0,
                    StartNumber = 1000,
                    Parameter1 = "I",
                    Parameter2 = "A",
                };

                CounterDefinition Quote_Import_Ocean_Counter = new CounterDefinition()
                {
                    Id = IdCounter.GetNumber("CounterDefinition", 0).ToString(),
                    CounterId = quoteCounter.Id,
                    Tenant = 0,
                    StartNumber = 1000,
                    Parameter1 = "I",
                    Parameter2 = "O",
                };

                CounterDefinition Quote_Import_Inland_Counter = new CounterDefinition()
                {
                    Id = IdCounter.GetNumber("CounterDefinition", 0).ToString(),
                    CounterId = quoteCounter.Id,
                    Tenant = 0,
                    StartNumber = 1000,
                    Parameter1 = "I",
                    Parameter2 = "I",
                };


                CounterDefinitionRepository.Add(Quote_Export_Air_Counter);
                CounterDefinitionRepository.Add(Quote_Export_Ocean_Counter);
                CounterDefinitionRepository.Add(Quote_Export_Inland_Counter);
                CounterDefinitionRepository.Add(Quote_Import_Air_Counter);
                CounterDefinitionRepository.Add(Quote_Import_Ocean_Counter);
                CounterDefinitionRepository.Add(Quote_Import_Inland_Counter);


            }
            #endregion

            this.ObjectContext.SaveChanges();
        }
